//! |------------------|------------------------------|-----------------------------------------|------------------------------|
//! | Config           | `$XDG_CONFIG_HOME/bivvy`     | `~/Library/Application Support/bivvy`   | `%APPDATA%/bivvy`            |
//! | Data (state)     | `$XDG_DATA_HOME/bivvy`       | `~/Library/Application Support/bivvy`   | `%LOCALAPPDATA%/bivvy`       |
//! | Cache            | `$XDG_CACHE_HOME/bivvy`      | `~/Library/Caches/bivvy`                | `%LOCALAPPDATA%/bivvy/cache` |

use std::path::PathBuf;

/// Bivvy's configuration directory.
///
/// Stores user-level config files like `config.yml`.
///
/// Falls back to `$HOME/.config/bivvy` if the platform config dir
/// cannot be determined.
pub fn config_dir() -> PathBuf {
    dirs::config_dir()
        .unwrap_or_else(|| {
            dirs::home_dir()
                .unwrap_or_else(|| PathBuf::from("."))
                .join(".config")
        })
        .join("bivvy")
}

/// Bivvy's data directory.
///
/// Stores persistent user data: project state, templates, failure reports.
///
/// Falls back to `$HOME/.local/share/bivvy` if the platform data dir
/// cannot be determined.
pub fn data_dir() -> PathBuf {
    dirs::data_local_dir()
        .unwrap_or_else(|| {
            dirs::home_dir()
                .unwrap_or_else(|| PathBuf::from("."))
                .join(".local")
                .join("share")
        })
        .join("bivvy")
}

/// User global config file path.
///
/// Returns `<config_dir>/config.yml`.
pub fn user_config_file() -> PathBuf {
    config_dir().join("config.yml")
}

/// Per-project state directory.
///
/// Returns `<data_dir>/projects/<hash>`.
pub fn project_state_dir(project_hash: &str) -> PathBuf {
    data_dir().join("projects").join(project_hash)
}

/// Project index file path.
///
/// Returns `<data_dir>/projects/index.yml`.
pub fn project_index_file() -> PathBuf {
    data_dir().join("projects").join("index.yml")
}

/// User templates directory.
///
/// Returns `<data_dir>/templates`.
pub fn user_templates_dir() -> PathBuf {
    data_dir().join("templates")
}

/// Failure reports directory.
///
/// Returns `<data_dir>/failure-reports`.
pub fn failure_reports_dir() -> PathBuf {
    data_dir().join("failure-reports")
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn config_dir_uses_platform_config() {
        let dir = config_dir();
        assert!(dir.ends_with("bivvy"));
        // Must not contain ".bivvy" — that was the old hardcoded path
        assert!(
            !dir.to_string_lossy().contains(".bivvy"),
            "config_dir should use platform config dir, not ~/.bivvy: {:?}",
            dir
        );
    }

    #[test]
    fn data_dir_uses_platform_data() {
        let dir = data_dir();
        assert!(dir.ends_with("bivvy"));
        assert!(
            !dir.to_string_lossy().contains(".bivvy"),
            "data_dir should use platform data dir, not ~/.bivvy: {:?}",
            dir
        );
    }

    #[test]
    fn user_config_file_ends_with_config_yml() {
        let path = user_config_file();
        assert_eq!(path.file_name().unwrap(), "config.yml");
        assert!(path.starts_with(config_dir()));
    }

    #[test]
    fn project_state_dir_includes_hash() {
        let dir = project_state_dir("abc123");
        assert!(dir.ends_with("abc123"));
        assert!(dir.starts_with(data_dir()));
    }

    #[test]
    fn project_index_file_path() {
        let path = project_index_file();
        assert_eq!(path.file_name().unwrap(), "index.yml");
        assert!(path.starts_with(data_dir()));
    }

    #[test]
    fn user_templates_dir_under_data() {
        let dir = user_templates_dir();
        assert!(dir.ends_with("templates"));
        assert!(dir.starts_with(data_dir()));
    }

    #[test]
    fn failure_reports_dir_under_data() {
        let dir = failure_reports_dir();
        assert!(dir.ends_with("failure-reports"));
        assert!(dir.starts_with(data_dir()));
    }

    #[test]
    fn paths_are_absolute() {
        // On a normal system with a home directory, all paths should be absolute
        if dirs::config_dir().is_some() {
            assert!(config_dir().is_absolute());
        }
        if dirs::data_local_dir().is_some() {
            assert!(data_dir().is_absolute());
        }
    }
}

