                git_remote: None,
                name: "test".to_string(),
                last_accessed: Utc::now(),
            },
        );

        let removed = index.prune();
        assert!(removed.contains(&"test".to_string()));
        assert!(index.projects.is_empty());
    }

    #[test]
    fn project_index_prune_keeps_existing() {
