            git_remote: Some("https://github.com/test/repo".to_string()),
            name: "project".to_string(),
            last_accessed: Utc::now(),
        };

        let yaml = serde_yaml::to_string(&entry).unwrap();
        assert!(yaml.contains("project"));
        assert!(yaml.contains("github.com"));
    }
}

